13	@theme {
14	  /* Typography — Project-wide font stack (Apple-esque) */
15	  --font-display: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
16	  --font-body: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
17	  --font-classical: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", Roboto, sans-serif;
18	  --font-mono: "SF Mono", -apple-system, BlinkMacSystemFont, sans-serif;
19	
20	  --color-neural-emerald: var(--neural-emerald);
21	  --color-neural-rose: var(--neural-rose);
22	  --color-neural-amber: var(--neural-amber);
23	  --color-neural-blue: var(--neural-blue);
24	}
25	
26	@custom-variant dark (&:where(.dark, .dark *));
27	
