/* ═══════════════════════════════════════════════════════════════════
   @qoe/theme — tokens.css
   Design Tokens en 2 couches (source unique de vérité pour toutes les apps)
   ═══════════════════════════════════════════════════════════════════

   Layer 1 — Primitives brutes (zinc scale, vermillon scale, radii).
             ⚠️ JAMAIS utilisées directement par les composants.
             Référencées uniquement par les sémantiques (Layer 2).

   Layer 2 — Sémantiques (--background, --foreground, --primary...).
             ✅ C'est ce que les composants consomment (text-foreground, bg-primary).
             Seule cette couche change entre thèmes (.dark, [data-accent]).

   Décision produit : le thème par défaut est NEUTRE zinc/noir.
   Le vermillon #EE4B2B est relégué en accent brand OPT-IN via [data-accent]
   (voir themes.css). Le dashboard reste neutre ; un créateur peut activer
   l'accent brand sur son blog public uniquement.
   ═══════════════════════════════════════════════════════════════════ */


/* ─────────────────────────────────────────────
   LAYER 1 — Primitives brutes
   ───────────────────────────────────────────── */
:root {
  /* Neutrals — zinc scale */
  --zinc-0:   #ffffff;
  --zinc-50:  #fafafa;
  --zinc-100: #f4f4f5;
  --zinc-200: #e4e4e7;
  --zinc-300: #d4d4d8;
  --zinc-400: #a1a1aa;
  --zinc-500: #71717a;
  --zinc-600: #52525b;
  --zinc-700: #3f3f46;
  --zinc-800: #27272a;
  --zinc-900: #18181b;
  --zinc-950: #09090b;

  /* Brand — vermillon (accent optionnel, opt-in) */
  --vermillion-400: #E55A2E;
  --vermillion-500: #EE4B2B;
  --vermillion-600: #C7331A;

  /* Legacy neural accents (conservés pour rétro-compat, mappés sainement) */
  --neural-emerald: oklch(0.68 0.15 152);
  --neural-rose:    var(--vermillion-500);
  --neural-amber:   oklch(0.75 0.12 75);
  --neural-blue:    oklch(0.65 0.14 240);

  /* Radii de base */
  --radius-base: 0.5rem;
}


/* ─────────────────────────────────────────────
   LAYER 2 — Sémantiques (thème light neutre par défaut)
   ───────────────────────────────────────────── */
:root {
  /* Surfaces & texte */
  --background:          var(--zinc-0);
  --foreground:          var(--zinc-950);

  --card:                var(--zinc-0);
  --card-foreground:     var(--zinc-950);
  --popover:             var(--zinc-0);
  --popover-foreground:  var(--zinc-950);

  /* Primary = neutre zinc-950 (PAS de vermillon par défaut) */
  --primary:             var(--zinc-950);
  --primary-foreground:  var(--zinc-0);

  --secondary:           var(--zinc-100);
  --secondary-foreground:var(--zinc-950);

  --muted:               var(--zinc-100);
  --muted-foreground:    var(--zinc-500);

  --accent:              var(--zinc-100);
  --accent-foreground:   var(--zinc-950);

  --destructive:         var(--vermillion-600);

  --border:              var(--zinc-200);
  --input:               var(--zinc-200);
  --ring:                var(--zinc-950);

  /* Brand accent — opt-in, NON actif par défaut.
     Activé via [data-accent="vermillion"] (voir themes.css). */
  --accent-brand:        var(--vermillion-500);
  --accent-brand-fg:     var(--zinc-0);

  /* Charts */
  --chart-1: oklch(0.62 0.14 25);
  --chart-2: oklch(0.65 0.12 165);
  --chart-3: oklch(0.72 0.10 80);
  --chart-4: oklch(0.55 0.15 280);
  --chart-5: oklch(0.68 0.13 140);

  /* Sidebar */
  --sidebar:                 var(--zinc-0);
  --sidebar-foreground:      var(--zinc-950);
  --sidebar-primary:         var(--zinc-950);
  --sidebar-primary-foreground: var(--zinc-0);
  --sidebar-accent:          var(--zinc-100);
  --sidebar-accent-foreground: var(--zinc-950);
  --sidebar-border:          var(--zinc-200);
  --sidebar-ring:            var(--zinc-950);

  /* Grid décoratif (très subtil) */
  --grid-color: rgba(0, 0, 0, 0.015);

  /* ═══════════════════════════════════════════════════
     QOE.FI v2 — Design Tokens étendus (Nested Radius System)
     Conservés car utilisés par le devtools et plusieurs composants.
     Remappés sur les primitives zinc.
     ═══════════════════════════════════════════════════ */

  /* Brand vars (référence, pour color pickers settings) */
  --qoe-vermillion:       var(--vermillion-500);
  --qoe-vermillion-10:    rgba(238, 75, 43, 0.10);
  --qoe-vermillion-08:    rgba(238, 75, 43, 0.08);
  --qoe-vermillion-glow:  rgba(238, 75, 43, 0.15);

  /* Surface System — Layered Paper */
  --surface-0: var(--zinc-0);
  --surface-1: var(--zinc-50);
  --surface-2: var(--zinc-100);
  --surface-3: var(--zinc-200);

  /* Text Hierarchy */
  --text-primary:    var(--zinc-950);
  --text-secondary:  var(--zinc-600);
  --text-tertiary:   var(--zinc-400);
  --text-quaternary: var(--zinc-300);

  /* Border System */
  --border-subtle:  rgba(0, 0, 0, 0.04);
  --border-default: rgba(0, 0, 0, 0.08);
  --border-strong:  rgba(0, 0, 0, 0.14);

  /* Shadow Vocabulary — jamais de shadow dure */
  --shadow-card:        0 1px 2px rgba(0,0,0,0.01), 0 2px 4px rgba(0,0,0,0.015), 0 8px 16px rgba(0,0,0,0.015), 0 16px 32px rgba(0,0,0,0.01);
  --shadow-card-hover:  0 2px 4px rgba(0,0,0,0.02), 0 4px 8px rgba(0,0,0,0.02), 0 16px 32px rgba(0,0,0,0.02), 0 32px 64px rgba(0,0,0,0.02);
  --shadow-elevated:    0 1px 2px rgba(0,0,0,0.01), 0 4px 8px rgba(0,0,0,0.02), 0 16px 32px rgba(0,0,0,0.04), 0 32px 64px rgba(0,0,0,0.04);
  --shadow-sidebar:     2px 0 24px rgba(0,0,0,0.03);

  /* Radii imbriqués */
  --radius:          var(--radius-base);
  --radius-plateau:  4px;
  --radius-card:     4px;
  --radius-element:  2px;
  --radius-chip:     2px;
  --radius-button:   4px;
  --radius-icon:     2px;

  /* Easings */
  --spring-snappy: cubic-bezier(0.16, 1, 0.3, 1);
  --spring-gentle: cubic-bezier(0.4, 0, 0.2, 1);

  /* Carousel */
  --carousel-padding: calc(50vw - 320px + 1.5rem);
}

/* ═══════════════════════════════════════════════════════════════════
   @qoe/theme — themes.css
   Variantes de thème (override des sémantiques Layer 2)
   ═══════════════════════════════════════════════════════════════════

   Ici on bascule les valeurs sémantiques (--primary, --background, etc.)
   selon le mode (light/dark) ou l'accent brand choisi.
   Les composants n'ont rien à coder : ils consomment toujours les mêmes
   tokens sémantiques, c'est le sélecteur CSS qui décide de la valeur.

   Activation :
     - Dark mode : classe `.dark` sur <html> (via next-themes, attribute="class")
     - Accent vermillon : attribut `data-accent="vermillion"` sur <html>
       ou sur un sous-arbre <section data-accent="vermillion">
   ═══════════════════════════════════════════════════════════════════ */


/* ─────────────────────────────────────────────
   DARK MODE — bascule les sémantiques vers zinc sombre
   Le neutre zinc se prête naturellement au dark.
   ───────────────────────────────────────────── */
.dark {
  --background:          var(--zinc-950);
  --foreground:          var(--zinc-50);

  --card:                var(--zinc-900);
  --card-foreground:     var(--zinc-50);
  --popover:             var(--zinc-900);
  --popover-foreground:  var(--zinc-50);

  --primary:             var(--zinc-50);
  --primary-foreground:  var(--zinc-950);

  --secondary:           var(--zinc-800);
  --secondary-foreground:var(--zinc-50);

  --muted:               var(--zinc-800);
  --muted-foreground:    var(--zinc-400);

  --accent:              var(--zinc-800);
  --accent-foreground:   var(--zinc-50);

  --border:              var(--zinc-800);
  --input:               var(--zinc-800);
  --ring:                var(--zinc-50);

  --sidebar:                 var(--zinc-950);
  --sidebar-foreground:      var(--zinc-50);
  --sidebar-primary:         var(--zinc-50);
  --sidebar-primary-foreground: var(--zinc-950);
  --sidebar-accent:          var(--zinc-800);
  --sidebar-accent-foreground: var(--zinc-50);
  --sidebar-border:          var(--zinc-800);
  --sidebar-ring:            var(--zinc-50);

  --grid-color: rgba(255, 255, 255, 0.02);

  /* Surface & text overrides (Layer 2 v2) */
  --surface-0: var(--zinc-950);
  --surface-1: var(--zinc-900);
  --surface-2: var(--zinc-800);
  --surface-3: var(--zinc-700);

  --text-primary:    var(--zinc-50);
  --text-secondary:  var(--zinc-400);
  --text-tertiary:   var(--zinc-500);
  --text-quaternary: var(--zinc-600);

  --border-subtle:  rgba(255, 255, 255, 0.04);
  --border-default: rgba(255, 255, 255, 0.08);
  --border-strong:  rgba(255, 255, 255, 0.14);
}


/* ─────────────────────────────────────────────
   ACCENT BRAND — vermillon (OPT-IN)

   Le dashboard reste neutre par défaut. Un créateur peut activer
   l'accent vermillon sur son blog public via <html data-accent="vermillion">.
   Cela remappe --primary vers le vermillon, sans toucher au reste.
   ───────────────────────────────────────────── */
[data-accent="vermillion"] {
  --primary:             var(--vermillion-500);
  --primary-foreground:  var(--zinc-0);
  --ring:                var(--vermillion-500);
  --sidebar-primary:         var(--vermillion-500);
  --sidebar-primary-foreground: var(--zinc-0);
  --sidebar-ring:            var(--vermillion-500);
  --accent-brand:        var(--vermillion-500);
}

/* ═══════════════════════════════════════════════════════════════════
   @qoe/theme — base.css
   Base layer : reset léger + classes utilitaires transverses.
   Ce qui est COMMUN à toutes les apps et n'a pas sa place dans un
   globals.css local.
   ═══════════════════════════════════════════════════════════════════ */

@layer base {
  * {
    border-color: var(--border);
    outline-color: color-mix(in oklch, var(--ring) 50%, transparent);
  }
  body {
    background: var(--surface-1);
    color: var(--foreground);
    font-feature-settings: "rlig" 1, "calt" 1;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
  html {
    scroll-behavior: smooth;
    scrollbar-gutter: stable;
  }
}

@layer components {
  /* Glass panel (Navbar & overlays) */
  .glass-panel {
    background: rgba(255, 255, 255, 0.75);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(0, 0, 0, 0.06);
  }
  .dark .glass-panel {
    background: rgba(9, 9, 11, 0.75);
    border-color: rgba(255, 255, 255, 0.06);
  }

  .crimson-gradient {
    background: var(--vermillion-500);
  }

  /* Organic glow decorations (très subtil) */
  .organic-glow {
    position: absolute;
    filter: blur(120px);
    opacity: 0.1;
    z-index: -10;
    border-radius: 9999px;
  }

  /* Reveal animation */
  .reveal {
    opacity: 0;
    transform: translateY(2rem);
    transition: opacity 1000ms cubic-bezier(0.16, 1, 0.3, 1),
                transform 1000ms cubic-bezier(0.16, 1, 0.3, 1);
  }
  .reveal.active {
    opacity: 1;
    transform: translateY(0);
  }

  /* Shimmer loading */
  .shimmer {
    position: relative;
    overflow: hidden;
  }
  .shimmer::before {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    animation: qoe-shimmer 2s infinite;
    background: linear-gradient(
      to right,
      transparent,
      rgba(0, 0, 0, 0.05),
      transparent
    );
  }

  /* Fade gradient mask */
  .text-fade-gradient {
    -webkit-mask-image: linear-gradient(to bottom, black 50%, transparent 100%);
    mask-image: linear-gradient(to bottom, black 50%, transparent 100%);
  }

  .font-editorial {
    font-variant-ligatures: common-ligatures discretionary-ligatures;
    font-feature-settings: "dlig" on, "ss01" on, "ss02" on, "cv10" on, "kern" on;
  }

  /* Custom thin scrollbar */
  .custom-scrollbar::-webkit-scrollbar { width: 4px; }
  .custom-scrollbar::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.03);
    border-radius: 4px;
  }
  .custom-scrollbar::-webkit-scrollbar-thumb {
    background: rgba(0, 0, 0, 0.12);
    border-radius: 4px;
  }
  .custom-scrollbar::-webkit-scrollbar-thumb:hover {
    background: rgba(0, 0, 0, 0.2);
  }

  /* Hide scrollbar entirely */
  .scrollbar-none::-webkit-scrollbar { display: none; }
  .scrollbar-none {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }
}

/* ─── Keyframes ─── */
@keyframes qoe-shimmer {
  100% { transform: translateX(100%); }
}

@keyframes marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

.animate-marquee {
  animation: marquee 40s linear infinite;
}
.animate-marquee:hover {
  animation-play-state: paused;
}

/* Responsive carousel padding (mobile) */
@media (max-width: 640px) {
  :root {
    --carousel-padding: 1rem;
  }
}

/* ═══════════════════════════════════════════════════════════════════
   @qoe/theme/styles — POINT D'ENTRÉE UNIQUE pour toutes les apps
   ═══════════════════════════════════════════════════════════════════

   Usage dans apps/*/src/app/layout.tsx :
     import "@qoe/theme/styles";

   Ce fichier assemble :
     1. Tailwind v4 (engine)
     2. tw-animate-css (animations utilitaires)
     3. tokens.css    → primitives + sémantiques (zinc neutre par défaut)
     4. themes.css    → variantes (.dark, [data-accent="vermillion"])
     5. base.css      → reset + classes transverses
     6. Le bridge Tailwind @theme inline (mappe --color-* vers les tokens)
     7. Styles éditeur ProseMirror (partagés dashboard + feed)

   Les apps ne gardent dans leur globals.css local QUE les overrides
   réellement spécifiques (voire rien du tout).
   ═══════════════════════════════════════════════════════════════════ */

@import "tailwindcss";
@import "tw-animate-css";

@import "./tokens.css";
@import "./themes.css";
@import "./base.css";


/* ─── @theme : expose les fonts + neural colors à Tailwind v4 ─── */
@theme {
  /* Typography — Project-wide font stack (Apple-esque) */
  --font-display: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-body: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-classical: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", Roboto, sans-serif;
  --font-mono: "SF Mono", -apple-system, BlinkMacSystemFont, sans-serif;

  --color-neural-emerald: var(--neural-emerald);
  --color-neural-rose: var(--neural-rose);
  --color-neural-amber: var(--neural-amber);
  --color-neural-blue: var(--neural-blue);
}

/* Dark mode via classe .dark (compat next-themes attribute="class") */
@custom-variant dark (&:where(.dark, .dark *));


/* ─── Bridge shadcn/ui ↔ Tailwind : mappe --color-* vers nos tokens ─── */
@theme inline {
  --font-heading: var(--font-sans);
  --font-sans: var(--font-sans);

  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);

  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);

  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --color-foreground: var(--foreground);
  --color-background: var(--background);

  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
}


/* ─── Tiptap / ProseMirror editor styles (partagés dashboard + feed) ─── */
.ProseMirror {
  outline: none;
}
.ProseMirror p {
  margin-bottom: 1.25rem;
}
.ProseMirror h1 {
  font-size: 2.25rem;
  font-weight: 800;
  line-height: 1.2;
  margin-top: 2rem;
  margin-bottom: 1rem;
}
.ProseMirror h2 {
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1.3;
  margin-top: 1.75rem;
  margin-bottom: 0.75rem;
}
.ProseMirror h3 {
  font-size: 1.35rem;
  font-weight: 600;
  line-height: 1.4;
  margin-top: 1.5rem;
  margin-bottom: 0.5rem;
}
.ProseMirror ul {
  list-style-type: disc;
  padding-left: 1.5rem;
  margin-bottom: 1.25rem;
}
.ProseMirror ol {
  list-style-type: decimal;
  padding-left: 1.5rem;
  margin-bottom: 1.25rem;
}
.ProseMirror blockquote {
  border-left: 4px solid var(--border);
  padding-left: 1rem;
  font-style: italic;
  color: var(--muted-foreground);
  margin-bottom: 1.25rem;
}
.ProseMirror pre {
  background-color: var(--muted);
  border: 1px solid var(--border);
  padding: 1rem;
  border-radius: var(--radius);
  font-family: var(--font-mono);
  font-size: 0.875rem;
  overflow-x: auto;
  margin-bottom: 1.25rem;
}
.ProseMirror code {
  background-color: var(--muted);
  padding: 0.2rem 0.4rem;
  border-radius: calc(var(--radius) * 0.5);
  font-family: var(--font-mono);
  font-size: 0.875rem;
}

// ═══════════════════════════════════════════════════════════════════
// 🎨 @qoe/theme — types.ts
// Types partagés pour le système de thème multi-apps + tenant.
// ═══════════════════════════════════════════════════════════════════

/** Modes de thème gérés par next-themes. */
export type ThemeMode = "light" | "dark" | "system";

/** Variantes d'accent brand activables (opt-in). */
export type AccentVariant = "none" | "vermillion";

/**
 * Données de branding d'un créateur, lues depuis la DB (User).
 * Utilisées par <ThemeStyle /> pour injecter les overrides tenant en SSR.
 *
 * Tous les champs sont optionnels : un créateur sans branding repose
 * sur les tokens neutres par défaut.
 */
export interface CreatorTheme {
  /** Couleur d'accent HEX (ex: "#EE4B2B"). Override --primary sur le sous-arbre. */
  accentColor?: string | null;
  /** Famille de police active (clé de registre, ex: "sans" | "serif" | "mono"). */
  fontFamily?: string | null;
  /** URL du logo créateur. */
  logoUrl?: string | null;
  /** Texte hero affiché en haut du blog. */
  heroText?: string | null;
  /** URL d'une image de header. */
  headerImageUrl?: string | null;
  /** Texte de footer. */
  footerText?: string | null;
  /** Mode de thème forcé pour le blog tenant ("light" | "dark" | "system"). */
  themeMode?: string | null;
  /** Style de layout ("minimal" | "magazine" | "brutalist"...). */
  layoutStyle?: string | null;
}

