// ═══════════════════════════════════════════════════════════════════
// 🎨 @qoe/theme — types.ts
// Types partagés pour le système de thème multi-apps + tenant.
// ═══════════════════════════════════════════════════════════════════

/** Modes de thème gérés par next-themes. */
export type ThemeMode = "light" | "dark" | "system";

/** Variantes d'accent brand activables (opt-in). */
export type AccentVariant = "none" | "vermillion";

/**
 * Données de branding d'un créateur, lues depuis la DB (User).
 * Utilisées par <ThemeStyle /> pour injecter les overrides tenant en SSR.
 *
 * Tous les champs sont optionnels : un créateur sans branding repose
 * sur les tokens neutres par défaut.
 */
export interface CreatorTheme {
  /** Couleur d'accent HEX (ex: "#EE4B2B"). Override --primary sur le sous-arbre. */
  accentColor?: string | null;
  /** Famille de police active (clé de registre, ex: "sans" | "serif" | "mono"). */
  fontFamily?: string | null;
  /** URL du logo créateur. */
  logoUrl?: string | null;
  /** Texte hero affiché en haut du blog. */
  heroText?: string | null;
  /** URL d'une image de header. */
  headerImageUrl?: string | null;
  /** Texte de footer. */
  footerText?: string | null;
  /** Mode de thème forcé pour le blog tenant ("light" | "dark" | "system"). */
  themeMode?: string | null;
  /** Style de layout ("minimal" | "magazine" | "brutalist"...). */
  layoutStyle?: string | null;
}

// ═══════════════════════════════════════════════════════════════════
// 📋 @qoe/theme — registry.ts
// Registre type-safe des thèmes et accents disponibles.
// Utilisé par les settings créateur et l'admin pour lister les options.
// ═══════════════════════════════════════════════════════════════════

import type { AccentVariant, ThemeMode } from "./types";

/** Thèmes (modes light/dark) exposés côté UI. */
export const THEMES = {
  light: { id: "light", label: "Light", dataTheme: "light" },
  dark: { id: "dark", label: "Dark", dataTheme: "dark" },
} as const;

/** Accents brand activables (opt-in). */
export const ACCENTS = {
  none: { id: "none", label: "Neutre", dataAccent: null },
  vermillion: { id: "vermillion", label: "Vermillon", dataAccent: "vermillion" },
} as const;

export type ThemeId = keyof typeof THEMES;
export type AccentId = keyof typeof ACCENTS;

/**
 * Convertit un ThemeMode stocké en DB ("light" | "dark" | "system")
 * en valeur utilisable par next-themes `forcedTheme`.
 * "system" → undefined (next-themes suit le système, pas de forçage).
 */
export function resolveForcedTheme(mode: ThemeMode | string | null | undefined) {
  if (mode === "light" || mode === "dark") return mode;
  return undefined; // "system" ou null → next-themes gère
}

/**
 * Mappe un accentColor HEX libre (choisi par le créateur) vers une
 * AccentVariant connue du registre, ou "none" si non reconnu.
 */
export function resolveAccentFromColor(color: string | null | undefined): AccentVariant {
  if (!color) return "none";
  const normalized = color.trim().toLowerCase();
  if (normalized === "#ee4b2b" || normalized === "var(--vermillion-500)") {
    return "vermillion";
  }
  // Couleur custom → traitée comme "none" côté variant,
  // mais l'override --primary sera injecté par <ThemeStyle>.
  return "none";
}

"use client";

// ═══════════════════════════════════════════════════════════════════
// 🌗 @qoe/theme — ThemeProvider.tsx
// Wrapper next-themes (light/dark/system), source unique pour toutes les apps.
// ═══════════════════════════════════════════════════════════════════

import * as React from "react";
import { ThemeProvider as NextThemesProvider } from "next-themes";

// Silence le faux positif React 19 sur les <script> en dev
// (next-themes en injecte un pour éviter le FOUC).
if (typeof window !== "undefined" && process.env.NODE_ENV === "development") {
  const orig = console.error;
  console.error = (...args: unknown[]) => {
    if (
      typeof args[0] === "string" &&
      args[0].includes("Encountered a script tag while rendering React component")
    ) {
      return;
    }
    orig.apply(console, args);
  };
}

export function ThemeProvider({
  children,
  ...props
}: React.ComponentProps<typeof NextThemesProvider>) {
  return <NextThemesProvider {...props}>{children}</NextThemesProvider>;
}

// ═══════════════════════════════════════════════════════════════════
// 🎨 @qoe/theme — ThemeStyle.tsx
// Server Component : injecte les overrides de tokens tenant en SSR (zéro FOUC).
// ═══════════════════════════════════════════════════════════════════
//
// Remplace l'ancienne approche ad-hoc d'apps/web (objet customStyle inline
// avec "--tenant-accent": accentColor || "hsl(var(--primary))" — bug car
// les tokens ne sont pas en hsl).
//
// Ici on override directement --primary (et dérivés) sur :root du sous-arbre,
// ce que les composants consomment déjà via bg-primary / text-primary.

import * as React from "react";
import type { CreatorTheme } from "./types";

interface ThemeStyleProps {
  /** Données de branding créateur (depuis la DB). */
  creator: CreatorTheme;
  /** Scope CSS (défaut : ":root" — toute la page). Pour un sous-arbre, passer un sélecteur. */
  scope?: string;
}

/**
 * Construit le dict des overrides de tokens pour un créateur.
 * Exporté pour permettre tests / preview / admin.
 */
export function buildCreatorVars(creator: CreatorTheme): Record<string, string> {
  const vars: Record<string, string> = {};

  if (creator.accentColor) {
    vars["--primary"] = creator.accentColor;
    vars["--ring"] = creator.accentColor;
    vars["--sidebar-primary"] = creator.accentColor;
    vars["--sidebar-ring"] = creator.accentColor;
    vars["--accent-brand"] = creator.accentColor;
  }

  if (creator.fontFamily) {
    // Mappe la clé famille vers la variable CSS --font-<key> exposée par @theme.
    vars["--font-active"] = `var(--font-${creator.fontFamily})`;
  }

  return vars;
}

/**
 * Server Component qui rend un <style> injectant les vars tenant.
 * À placer en haut du layout tenant (apps/web), avant {children}.
 */
export function ThemeStyle({ creator, scope = ":root" }: ThemeStyleProps) {
  const vars = buildCreatorVars(creator);

  if (Object.keys(vars).length === 0) return null;

  const css = Object.entries(vars)
    .map(([k, v]) => `${k}: ${v};`)
    .join(" ");

  return (
    <style
      dangerouslySetInnerHTML={{ __html: `${scope} { ${css} }` }}
    />
  );
}

// ═══════════════════════════════════════════════════════════════════
// 🔧 @qoe/theme — tokens.ts
// Helpers runtime pour lire les tokens CSS résolus (utile pour charts/canvas).
// ═══════════════════════════════════════════════════════════════════

/**
 * Lit la valeur résolue d'un token sémantique au runtime.
 * @param name Nom complet du token (ex: "--primary", "--background").
 * @returns La valeur calculée (ex: "#09090b" en light, "#fafafa" en dark), ou "" si indispo.
 *
 * @example
 * token("--primary");            // → "#09090b"
 * token("--chart-1");            // → "oklch(0.62 0.14 25)"
 *
 * SSR-safe : retourne "" côté serveur (pas de document).
 */
export function token(name: string): string {
  if (typeof window === "undefined") return "";
  return getComputedStyle(document.documentElement)
    .getPropertyValue(name)
    .trim();
}

/**
 * Lit plusieurs tokens d'un coup. Pratique pour alimenter un palette de charts.
 * @example
 * const palette = tokens(["--chart-1", "--chart-2", "--chart-3"]);
 */
export function tokens(names: string[]): Record<string, string> {
  if (typeof window === "undefined") {
    return Object.fromEntries(names.map((n) => [n, ""]));
  }
  const root = document.documentElement;
  const cs = getComputedStyle(root);
  return Object.fromEntries(names.map((n) => [n, cs.getPropertyValue(n).trim()]));
}

