} as const;

/** @deprecated Les familles sont gérées via @theme (voir @qoe/theme/styles). */
export const FONTS = {
  sans: '"Inter", "Geist", system-ui, sans-serif',
  serif: '"Geist", "Playfair Display", Georgia, serif',
  mono: '"JetBrains Mono", "Fira Code", monospace',
