} as const;

/** @deprecated Utiliser les breakpoints Tailwind. */
export const BREAKPOINTS = {
  sm: 640,
  md: 768,
  lg: 1024,
  xl: 1280,
  "2xl": 1536,
} as const;

/** @deprecated Utiliser les utilitaires Tailwind (duration-150...). */
export const DURATIONS = {
  fast: 150,
  normal: 250,
  slow: 400,
  slower: 600,
} as const;

