import { notFound } from "next/navigation";
import { prisma } from "@qoe/db/client";
import Link from "next/link";
import { Metadata } from "next";
import { SocialIcon, TenantHeader, SubscribeForm } from "@qoe/ui";

interface PageProps {
  params: Promise<{ domain: string }>;
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { domain } = await params;
  const decodedDomain = decodeURIComponent(domain);

  const creator = await prisma.user.findFirst({
    where: {
      OR: [
        { subdomain: decodedDomain },
        { customDomain: decodedDomain },
      ],
    },
  });

  if (!creator) return {};

  return {
    title: creator.seoTitle || `${creator.name} | ${decodedDomain}`,
    description: creator.seoDescription || creator.heroText || `Explore the thoughts and articles of ${creator.name}.`,
    robots: {
      index: creator.allowIndexing,
      follow: creator.allowIndexing,
    },
