  const locale = await getLanguage();
  const tolgee = await getTolgee();
  // Tolgee tolère un objet vide pour staticData en dev
  let staticData: any = {};
  try {
    staticData = (await tolgee.loadRequired()) ?? {};
  } catch {
    staticData = {};
