  display: '"Geist", "Playfair Display", serif',
} as const;

/** @deprecated Utiliser les breakpoints Tailwind. */
export const BREAKPOINTS = {
  sm: 640,
  md: 768,
  lg: 1024,
  xl: 1280,
  "2xl": 1536,
