274	/* ─── Base Layer ─── */
275	@layer base {
276	  * {
277	    @apply border-border outline-ring/50;
278	  }
279	  body {
280	    @apply font-body antialiased bg-background text-foreground;
281	    background: var(--surface-1);
282	  }
283	  html {
284	    @apply font-sans scroll-smooth;
285	    scrollbar-gutter: stable;
286	  }
287	}
288	
289	/* ─── Component Layer ─── */
290	@layer components {
291	  /* Glass panel used in Navbar and overlays */
292	  .glass-panel {
293	    background: rgba(255, 255, 255, 0.75);
294	    backdrop-filter: blur(20px);
295	    -webkit-backdrop-filter: blur(20px);
296	    border: 1px solid rgba(0, 0, 0, 0.06);
297	  }
298	
299	  .crimson-gradient {
300	    background: #EE4B2B;
301	  }
302	
303	  .ambient-glow {
304	    /* Removed for clean design */
305	  }
306	
307	  /* Organic glow decorations */
308	  .organic-glow {
309	    @apply absolute filter blur-[120px] opacity-10 -z-10 rounded-full;
310	  }
311	
312	  /* Reveal animation base state */
313	  .reveal {
314	    @apply opacity-0 translate-y-8 transition-all duration-1000 ease-[cubic-bezier(0.16,1,0.3,1)];
315	  }
316	  .reveal.active {
317	    @apply opacity-100 translate-y-0;
318	  }
319	
320	  /* Shimmer loading effect */
321	  .shimmer {
322	    @apply relative overflow-hidden before:absolute before:inset-0 before:-translate-x-full before:animate-[shimmer_2s_infinite] before:bg-linear-to-r before:from-transparent before:via-black/5 before:to-transparent;
323	  }
324	
325	  /* Rauno Freiberg inspired premium effects */
326	  .text-fade-gradient {
327	    mask-image: linear-gradient(to bottom, black 50%, transparent 100%);
328	    -webkit-mask-image: linear-gradient(to bottom, black 50%, transparent 100%);
329	  }
330	
331	  .font-editorial {
332	    font-variant-ligatures: common-ligatures discretionary-ligatures;
333	    font-feature-settings: "dlig" on, "ss01" on, "ss02" on, "cv10" on, "kern" on;
334	  }
335	
336	  /* Custom scrollbar utility */
337	  .custom-scrollbar::-webkit-scrollbar {
338	    width: 4px;
339	  }
340	  .custom-scrollbar::-webkit-scrollbar-track {
341	    background: rgba(0, 0, 0, 0.03);
342	    border-radius: 4px;
343	  }
344	  .custom-scrollbar::-webkit-scrollbar-thumb {
345	    background: rgba(0, 0, 0, 0.12);
346	    border-radius: 4px;
347	  }
348	  .custom-scrollbar::-webkit-scrollbar-thumb:hover {
349	    background: rgba(0, 0, 0, 0.2);
350	  }
351	}
352	
353	/* ─── Keyframes ─── */
354	@keyframes shimmer {
355	  100% { transform: translateX(100%); }
356	}
357	
358	@keyframes marquee {
359	  0% { transform: translateX(0); }
360	  100% { transform: translateX(-50%); }
361	}
362	
363	.animate-marquee {
364	  animation: marquee 40s linear infinite;
365	}
366	.animate-marquee:hover {
367	  animation-play-state: paused;
368	}
