223	  --sidebar-border: #e4e4e7;
224	  --sidebar-ring: #EE4B2B;
225	
226	  /* Grid background */
227	  --grid-color: rgba(238, 75, 43, 0.015);
228	
229	  /* ═══════════════════════════════════════════════════
230	     QOE.FI v2 — Design Tokens (Nested Radius System)
231	     ═══════════════════════════════════════════════════ */
232	
233	  /* Brand */
234	  --qoe-vermillion: #EE4B2B;
235	  --qoe-vermillion-10: rgba(238, 75, 43, 0.10);
236	  --qoe-vermillion-08: rgba(238, 75, 43, 0.08);
237	  --qoe-vermillion-glow: rgba(238, 75, 43, 0.15);
238	
239	  /* Surface System — Layered Paper */
240	  --surface-0: #FFFFFF;
241	  --surface-1: #FAFAFA;
242	  --surface-2: #F5F5F4;
243	  --surface-3: #EBEBEA;
244	
245	  /* Text Hierarchy */
246	  --text-primary: #0D0D0D;
247	  --text-secondary: #525252;
248	  --text-tertiary: #A3A3A3;
249	  --text-quaternary: #D4D4D4;
250	
251	  /* Border System */
252	  --border-subtle:  rgba(0, 0, 0, 0.04);
253	  --border-default: rgba(0, 0, 0, 0.08);
254	  --border-strong:  rgba(0, 0, 0, 0.14);
255	
256	  /* Shadow Vocabulary — Jamais de shadow dure */
257	  --shadow-card: 0 1px 2px rgba(0,0,0,0.01), 0 2px 4px rgba(0,0,0,0.015), 0 8px 16px rgba(0,0,0,0.015), 0 16px 32px rgba(0,0,0,0.01);
258	  --shadow-card-hover: 0 2px 4px rgba(0,0,0,0.02), 0 4px 8px rgba(0,0,0,0.02), 0 16px 32px rgba(0,0,0,0.02), 0 32px 64px rgba(0,0,0,0.02);
259	  --shadow-elevated: 0 1px 2px rgba(0,0,0,0.01), 0 4px 8px rgba(0,0,0,0.02), 0 16px 32px rgba(0,0,0,0.04), 0 32px 64px rgba(0,0,0,0.04);
260	  --shadow-sidebar: 2px 0 24px rgba(0,0,0,0.03);
261	
262	  --radius-plateau: 4px;   /* Conteneur plateau extérieur */
263	  --radius-card:    4px;   /* Carte dans plateau (plateau - padding) */
264	  --radius-element: 2px;   /* Éléments dans carte */
265	  --radius-chip:    2px;   /* Pills / badges */
266	  --radius-button:  4px;   /* Boutons */
267	  --radius-icon:    2px;   /* Avatars / icon containers */
268	
269	  /* Animation Speeds */
270	  --spring-snappy: cubic-bezier(0.16, 1, 0.3, 1);
271	  --spring-gentle: cubic-bezier(0.4, 0, 0.2, 1);
272	}
273	
274	/* ─── Base Layer ─── */
275	@layer base {
276	  * {
277	    @apply border-border outline-ring/50;
278	  }
279	  body {
280	    @apply font-body antialiased bg-background text-foreground;
281	    background: var(--surface-1);
282	  }
283	  html {
284	    @apply font-sans scroll-smooth;
285	    scrollbar-gutter: stable;
286	  }
287	}
288	
289	/* ─── Component Layer ─── */
290	@layer components {
291	  /* Glass panel used in Navbar and overlays */
292	  .glass-panel {
293	    background: rgba(255, 255, 255, 0.75);
294	    backdrop-filter: blur(20px);
295	    -webkit-backdrop-filter: blur(20px);
296	    border: 1px solid rgba(0, 0, 0, 0.06);
297	  }
298	
299	  .crimson-gradient {
300	    background: #EE4B2B;
301	  }
302	
303	  .ambient-glow {
304	    /* Removed for clean design */
305	  }
306	
307	  /* Organic glow decorations */
308	  .organic-glow {
309	    @apply absolute filter blur-[120px] opacity-10 -z-10 rounded-full;
310	  }
311	
312	  /* Reveal animation base state */
313	  .reveal {
314	    @apply opacity-0 translate-y-8 transition-all duration-1000 ease-[cubic-bezier(0.16,1,0.3,1)];
315	  }
316	  .reveal.active {
317	    @apply opacity-100 translate-y-0;
318	  }
319	
320	  /* Shimmer loading effect */
321	  .shimmer {
322	    @apply relative overflow-hidden before:absolute before:inset-0 before:-translate-x-full before:animate-[shimmer_2s_infinite] before:bg-linear-to-r before:from-transparent before:via-black/5 before:to-transparent;
323	  }
324	
325	  /* Rauno Freiberg inspired premium effects */
326	  .text-fade-gradient {
327	    mask-image: linear-gradient(to bottom, black 50%, transparent 100%);
328	    -webkit-mask-image: linear-gradient(to bottom, black 50%, transparent 100%);
329	  }
330	
331	  .font-editorial {
332	    font-variant-ligatures: common-ligatures discretionary-ligatures;
333	    font-feature-settings: "dlig" on, "ss01" on, "ss02" on, "cv10" on, "kern" on;
334	  }
335	
336	  /* Custom scrollbar utility */
337	  .custom-scrollbar::-webkit-scrollbar {
338	    width: 4px;
339	  }
340	  .custom-scrollbar::-webkit-scrollbar-track {
341	    background: rgba(0, 0, 0, 0.03);
342	    border-radius: 4px;
343	  }
344	  .custom-scrollbar::-webkit-scrollbar-thumb {
345	    background: rgba(0, 0, 0, 0.12);
346	    border-radius: 4px;
347	  }
348	  .custom-scrollbar::-webkit-scrollbar-thumb:hover {
349	    background: rgba(0, 0, 0, 0.2);
350	  }
351	}
352	
353	/* ─── Keyframes ─── */
354	@keyframes shimmer {
355	  100% { transform: translateX(100%); }
356	}
357	
358	@keyframes marquee {
359	  0% { transform: translateX(0); }
360	  100% { transform: translateX(-50%); }
361	}
362	
363	.animate-marquee {
364	  animation: marquee 40s linear infinite;
365	}
366	.animate-marquee:hover {
367	  animation-play-state: paused;
368	}
369	
370	/* ─── Tiptap Editor (ProseMirror) ─── */
371	.ProseMirror {
372	  outline: none;
373	}
374	.ProseMirror p {
375	  margin-bottom: 1.25rem;
376	}
377	.ProseMirror h1 {
378	  font-size: 2.25rem;
379	  font-weight: 800;
380	  line-height: 1.2;
381	  margin-top: 2rem;
382	  margin-bottom: 1rem;
383	}
384	.ProseMirror h2 {
385	  font-size: 1.75rem;
386	  font-weight: 700;
387	  line-height: 1.3;
388	  margin-top: 1.75rem;
389	  margin-bottom: 0.75rem;
390	}
391	.ProseMirror h3 {
392	  font-size: 1.35rem;
393	  font-weight: 600;
394	  line-height: 1.4;
395	  margin-top: 1.5rem;
396	  margin-bottom: 0.5rem;
397	}
398	.ProseMirror ul {
399	  list-style-type: disc;
400	  padding-left: 1.5rem;
401	  margin-bottom: 1.25rem;
402	}
403	.ProseMirror ol {
404	  list-style-type: decimal;
405	  padding-left: 1.5rem;
406	  margin-bottom: 1.25rem;
407	}
408	.ProseMirror blockquote {
409	  border-left: 4px solid oklch(from var(--border) l c h);
410	  padding-left: 1rem;
411	  font-style: italic;
412	  color: oklch(from var(--muted-foreground) l c h);
413	  margin-bottom: 1.25rem;
414	}
415	.ProseMirror pre {
416	  background-color: oklch(from var(--muted) l c h);
417	  border: 1px solid oklch(from var(--border) l c h);
418	  padding: 1rem;
419	  border-radius: var(--radius);
420	  font-family: var(--font-mono);
421	  font-size: 0.875rem;
422	  overflow-x: auto;
423	  margin-bottom: 1.25rem;
424	}
425	.ProseMirror code {
426	  background-color: oklch(from var(--muted) l c h);
427	  padding: 0.2rem 0.4rem;
428	  border-radius: calc(var(--radius) * 0.5);
429	  font-family: var(--font-mono);
430	  font-size: 0.875rem;
431	}
432	
433	/* Hide scrollbar for Chrome, Safari and Opera */
434	.scrollbar-none::-webkit-scrollbar {
435	  display: none;
436	}
437	/* Hide scrollbar for IE, Edge and Firefox */
438	.scrollbar-none {
439	  -ms-overflow-style: none;  /* IE and Edge */
440	  scrollbar-width: none;  /* Firefox */
441	}
442	
443	:root {
444	  --carousel-padding: calc(50vw - 320px + 1.5rem);
445	}
446	@media (max-width: 640px) {
447	  :root {
448	    --carousel-padding: 1rem;
449	  }
450	}

