310	  }
311	
312	  /* Reveal animation base state */
313	  .reveal {
314	    @apply opacity-0 translate-y-8 transition-all duration-1000 ease-[cubic-bezier(0.16,1,0.3,1)];
315	  }
316	  .reveal.active {
317	    @apply opacity-100 translate-y-0;
318	  }
