12	  const { domain } = await params;
13	  const decodedDomain = decodeURIComponent(domain);
14	
15	  const creator = await prisma.user.findFirst({
16	    where: {
17	      OR: [
18	        { subdomain: decodedDomain },
19	        { customDomain: decodedDomain },
20	      ],
