17	export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
18	  const { domain, slug } = await params;
19	  const decodedDomain = decodeURIComponent(domain);
20	  const decodedSlug = decodeURIComponent(slug);
21	
22	  const creator = await prisma.user.findFirst({
23	    where: {
24	      OR: [
25	        { subdomain: decodedDomain },
26	        { customDomain: decodedDomain },
27	      ],
28	    },
29	    include: {
30	      articles: {
31	        where: { slug: decodedSlug, published: true },
32	      },
33	    },
34	  });
35	
36	  if (!creator || creator.articles.length === 0) return {};
37	
38	  const article = creator.articles[0];
39	
40	  return {
41	    title: article.seoTitle || `${article.title} | ${creator.name}`,
42	    description: article.seoDescription || article.content.replace(/<[^>]*>?/gm, '').substring(0, 160),
43	    robots: {
44	      index: creator.allowIndexing,
45	      follow: creator.allowIndexing,
46	    },
47	    openGraph: {
48	      title: article.seoTitle || article.title,
49	      description: article.seoDescription || article.content.replace(/<[^>]*>?/gm, '').substring(0, 160),
50	      type: 'article',
51	      publishedTime: article.createdAt.toISOString(),
52	      authors: [creator.name || ''],
53	    }
54	  };
55	}
